def validate_request(value: object) -> InputValidator:
    """Validate without advancing input or inserting defaults; paths use canonical schema names."""
    errors: list[str] = []
    _validate42(value, "request", errors)
    if errors:
        raise TypeError("Invalid smallest.ai TTS request:\n" + "\n".join(errors))
    _validate46(value, "request", errors)
    accepts0 = not errors
    errors.clear()
    _validate47(value, "request", errors)
    accepts1 = not errors
    errors.clear()
    def validate_input(item: object, field: str = "text") -> None:
        errors: list[str] = []
        if accepts0:
            before = len(errors)
            _validate45(item, "text item", errors)
            if len(errors) == before:
                return
        if accepts1:
            before = len(errors)
            _validate23(item, "text item", errors)
            if len(errors) == before:
                return
        if not errors:
            errors.append("text item: streaming input is not supported by this request")
        raise TypeError("Invalid smallest.ai TTS input item:\n" + "\n".join(errors))
    return validate_input
